import json, re

lines = open('ios_crash.ips').readlines()
body_text = ''.join(lines[1:])
body_text_fixed = re.sub(r'\"vmregioninfo\"', '\"vmregioninfo_lower\"', body_text)
crash = json.loads(body_text_fixed)

# Check for any thread state, registers, or other helpful info
print('=== Thread 0 triggered state ===')
thread = crash['threads'][0]
if 'triggered' in thread:
    print(f'  triggered: {thread[\"triggered\"]}')

# Look for other threads with libcoreclr or interesting frames
images = crash.get('usedImages', [])
print('\n=== Threads with .NET frames ===')
for ti, t in enumerate(crash['threads']):
    for fi, f in enumerate(t['frames'][:5]):
        img = images[f['imageIndex']]
        if 'libcoreclr' in img.get('name','') or ('SampleMAUI' in img.get('name','') and f['imageIndex'] == 1):
            print(f'  Thread {ti} ({t.get(\"name\",\"unnamed\")}): frame #{fi} {img[\"name\"]}+0x{f[\"imageOffset\"]:x}')
            break

# Look for managed exception info in other crash fields
print('\n=== Other crash fields ===')
for key in sorted(crash.keys()):
    if key not in ['threads', 'usedImages', 'vmSummary', 'legacyInfo']:
        val = crash[key]
        if isinstance(val, (str, int, float, bool)):
            print(f'  {key}: {val}')
        elif isinstance(val, dict) and len(str(val)) < 300:
            print(f'  {key}: {json.dumps(val)}')
        elif isinstance(val, list) and len(val) < 10 and len(str(val)) < 300:
            print(f'  {key}: {json.dumps(val)}')
